import {useId,useLayoutEffect,useRef,useState} from 'react';
import './search.css';
export type FilterToken={id:string;label:string};
export type SearchValue={tokens:readonly FilterToken[];text:string};
export type Suggestion={id:string;label:string};
export type SearchAction=
 |{type:'textChanged';text:string;caret:number}
 |{type:'removeToken';id:string}
 |{type:'chooseSuggestion';suggestionId:string;replaceTokenId:string|null;caret:number}
 |{type:'clear'};
type Props={value:SearchValue;suggestions:readonly Suggestion[];onAction:(action:SearchAction)=>void;restoreCaret?:{revision:number;position:number}};
export function TokenSearch({value,suggestions,onAction,restoreCaret}:Props){
 const id=useId();const input=useRef<HTMLInputElement>(null);const [editing,setEditing]=useState<string|null>(null);const [active,setActive]=useState(-1);const [expanded,setExpanded]=useState(false);const [announcement,setAnnouncement]=useState('');
 useLayoutEffect(()=>{if(restoreCaret){const node=input.current;node?.focus();node?.setSelectionRange(restoreCaret.position,restoreCaret.position)}},[restoreCaret?.revision]);
 const focus=()=>input.current?.focus();
 const choose=(s:Suggestion)=>{onAction({type:'chooseSuggestion',suggestionId:s.id,replaceTokenId:editing,caret:input.current?.selectionStart??value.text.length});setAnnouncement((editing?'Replaced filter with ':'Added filter ')+s.label);setEditing(null);setExpanded(false);setActive(-1);focus()};
 const remove=(token:FilterToken)=>{onAction({type:'removeToken',id:token.id});if(editing===token.id)setEditing(null);setAnnouncement('Removed '+token.label);focus()};
 const shown=expanded&&suggestions.length>0;
 return <div className="token-search" onBlur={e=>{if(!e.currentTarget.contains(e.relatedTarget as Node|null)){setExpanded(false);setActive(-1)}}}>
  <label htmlFor={id}>Search workspace</label>
  <p id={id+'-help'} className="search-help">Type to search. Use arrow keys for suggestions. Tab to a filter to edit or remove it.</p>
  <div className="search-surface">
   <ol aria-label="Search filters">{value.tokens.map(token=><li key={token.id}><button type="button" aria-label={'Edit filter '+token.label} aria-pressed={editing===token.id} onClick={()=>{setEditing(token.id);setExpanded(true);setActive(-1);focus();setAnnouncement('Editing filter '+token.label+'. Choose a replacement suggestion.')}}>{token.label}</button><button type="button" aria-label={'Remove filter '+token.label} onClick={()=>remove(token)}>×</button></li>)}</ol>
   <input ref={input} id={id} type="text" role="combobox" aria-autocomplete="list" aria-expanded={shown} aria-controls={shown?id+'-suggestions':undefined} aria-activedescendant={shown&&active>=0&&active<suggestions.length?id+'-suggestion-'+active:undefined} aria-describedby={id+'-help'} value={value.text} onFocus={()=>setExpanded(true)} onChange={e=>{onAction({type:'textChanged',text:e.target.value,caret:e.target.selectionStart??e.target.value.length});setActive(-1);setExpanded(true)}} onKeyDown={e=>{
    if(e.key==='ArrowDown'&&suggestions.length){e.preventDefault();setExpanded(true);setActive(i=>(i+1)%suggestions.length)}
    else if(e.key==='ArrowUp'&&suggestions.length){e.preventDefault();setExpanded(true);setActive(i=>(i<=0?suggestions.length:i)-1)}
    else if(e.key==='Enter'&&shown&&suggestions[active]){e.preventDefault();choose(suggestions[active])}
    else if(e.key==='Escape'){e.preventDefault();setExpanded(false);setEditing(null);setActive(-1);setAnnouncement('Filter editing cancelled')}
    else if(e.key==='Backspace'&&!value.text&&value.tokens.length){e.preventDefault();remove(value.tokens[value.tokens.length-1])}
   }}/>
   <button type="button" onClick={()=>{onAction({type:'clear'});setEditing(null);setActive(-1);setExpanded(false);setAnnouncement('Search cleared');focus()}} disabled={!value.text&&!value.tokens.length}>Clear search</button>
  </div>
  {editing&&<p>Replacing {value.tokens.find(t=>t.id===editing)?.label}. <button type="button" onClick={()=>{setEditing(null);focus()}}>Cancel replacement</button></p>}
  {shown&&<ul id={id+'-suggestions'} role="listbox" aria-label="Search suggestions">{suggestions.map((s,index)=><li role="option" id={id+'-suggestion-'+index} aria-selected={active===index} key={s.id} onPointerDown={e=>e.preventDefault()} onClick={()=>choose(s)}>{s.label}</li>)}</ul>}
  <span className="search-sr" role="status">{announcement}</span>
 </div>;
}
// The application parses text, produces suggestions, handles actions, and supplies a
// new restoreCaret revision/position after choosing a suggestion or replacing a token.
// This editor never invents parser syntax, token IDs, or suggestion matching rules.
